<?php
declare(strict_types=1);namespace Liberu\Accounting\FixedAssets\Actions;use Liberu\Accounting\FixedAssets\Enums\AssetStatus;use Liberu\Accounting\FixedAssets\Exceptions\InvalidAsset;use Liberu\Accounting\FixedAssets\Models\{Asset,AssetBook};final class CapitalizeAsset {public function handle(Asset $asset,string $bookRef):Asset{if($asset->status!==AssetStatus::Acquired)throw new InvalidAsset('Only acquired assets can be capitalized.');if(blank($bookRef))throw new InvalidAsset('Asset book reference is required.');$asset->books()->create(['book_ref'=>$bookRef,'cost'=>$asset->cost,'net_book_value'=>$asset->cost]);$asset->update(['status'=>AssetStatus::Capitalized,'capitalized_on'=>now()->toDateString()]);return $asset->refresh();}}
